  'dl.docTitle': 'Draft League – draft your dream team and beat your friends | CM Reborn', 'dl.cta': 'Create a draft league', 'dl.ctaShort': 'Create league', 'dl.seeHow': 'How it works', 'dl.back': 'Back to CM Reborn',
  'dl.nav.how': 'How it works', 'dl.nav.fun': 'The fun', 'dl.nav.shots': 'Screenshots', 'dl.pill': 'New game mode · free',
  'dl.h1a': 'Draft your dream team.', 'dl.h1b': 'Beat your friends.', 'dl.lead': 'Everyone builds a fictional club from the 500 best players in the game – live, one pick at a time, with 60 seconds on the clock. Then you play a whole season against each other. When it ends, a new draft begins.',
  'dl.check.free': 'Free, in the browser', 'dl.check.friends': '2–16 clubs, with or without AI', 'dl.check.live': 'Live draft with voice chat', 'dl.check.nomoney': 'No wages or transfers – just football',
