  'land.docTitle': 'CM Reborn – the legendary football manager, free in your browser',
  'land.nav.features': 'Features', 'land.nav.screens': 'Screenshots', 'land.nav.ranking': 'Rankings', 'land.nav.faq': 'FAQ',
  'land.play': 'Play free now', 'land.playShort': 'Play now', 'land.seeScreens': 'See the game',
  'land.pill': 'New season · 40,000+ real players', 'land.h1a': 'The legend is back.', 'land.h1b': 'Now in your browser.',
  'land.lead': 'The classic football manager, reborn: build your dream team, unearth hidden gems, face the press and take your club to the top – with a match engine that thinks and AI managers who fight back.',
  'land.check.free': 'Free', 'land.check.nodl': 'No download', 'land.check.lang': "10 languages", 'land.check.save': 'Saves automatically',
  'land.floatGoal': 'GOAL! 89th minute', 'land.floatBid': 'Bidding war for your star',
  'land.alt.report': 'Match report with xG, momentum and heatmap', 'land.alt.mobile': 'The game on mobile',
  'land.tick1': "12' Through ball – and it's in the top corner!", 'land.tick2': 'Rumour: giants watching your captain', 'land.tick3': "67' Red card! The manager throws on another striker",
  'land.tick4': 'Press conference: “Do you still believe in the title?”', 'land.tick5': 'Scout: “He will be world class in three years”', 'land.tick6': 'Agent demands a new deal after five goals in a row',
  'land.tick7': 'The board: “We expect a top-3 finish”', 'land.tick8': "90+3' Stoppage-time equaliser – the stadium erupts",
  'land.stat.players': 'real players in two databases', 'land.stat.clubs': 'clubs', 'land.stat.leagues': 'leagues', 'land.stat.moments': 'actions simulated per match',
  'land.featuresTitle': 'Everything you loved – and everything you always missed', 'land.featuresSub': 'The classic depth of 2001 with a modern engine, beautiful design and play on every screen.',
  'land.f.engine.title': 'A match engine that thinks', 'land.f.engine.text': '240 actions per match, xG, momentum and heatmaps. Tactics matter – and there are no exploit formations.',
  'land.f.players.title': '40,000+ real players', 'land.f.players.text': 'Two databases: 22,700 players from 2026/27 and 35,000 from the original CM 01/02 database. 81 leagues and 1,375 clubs – from the Danish Superliga to the Premier League and the Champions League.',
  'land.f.scouting.title': 'Scouting with uncertainty', 'land.f.scouting.text': 'Your scouts see ranges, not the truth. Good scouts find wonderkids before anyone else.',
  'land.f.press.title': 'Press conferences and talks', 'land.f.press.text': 'Answer the journalists, praise or hairdryer the dressing room – in your own words.',
  'land.f.transfers.title': 'A living transfer market', 'land.f.transfers.text': 'Bidding wars, clubs returning with bigger bids, loans with options to buy and pushy agents.',
  'land.f.ai.title': 'AI opponents with a will', 'land.f.ai.text': 'Managers who scout your tactics and react mid-match. Players with demands, cliques and moods.',
  'land.f.ranking.title': 'Global leaderboards', 'land.f.ranking.text': 'Every season earns points for the job done. Overachieve with a small club and climb past the big-club managers.',
  'land.f.online.title': 'Online with friends', 'land.f.online.text': 'Run your own clubs in the same world – bid for each other\'s players and meet in the league.',
  'land.f.mobile.title': 'Anywhere, even offline', 'land.f.mobile.text': 'Play on desktop, tablet or phone. Install it as an app and carry on where you left off.',
  'land.nav.looks': 'Looks', 'land.looks.kicker': 'Two looks', 'land.looks.title': 'Modern – or exactly like 2001', 'land.looks.sub': 'Same game, same database. Pick a modern, mobile-friendly look or the classic CM 01/02 style with tabs, Back/Next and the old background photos.', 'land.looks.modern': 'Modern', 'land.looks.classic': 'Classic CM 01/02', 'land.looks.s.squad': 'Squad', 'land.looks.s.player': 'Player profile', 'land.looks.s.table': 'League table', 'land.looks.modern.text': 'Light or dark theme in your club colours, side menu, big numbers and charts. Built for phone, tablet and desktop.', 'land.looks.classic.text': 'Club-coloured title bar, tabs, green drop-down menus and the squad in two columns – just as you remember it. With rotating background photos and pixel look.', 'land.looks.play.modern': 'Play modern', 'land.looks.play.classic': 'Play classic', 'land.looks.note': 'You can switch look any time in Options – even in the middle of a career.',
  'land.s.classic.kicker': 'Classic CM 01/02', 'land.s.classic.title': 'Just as you remember it', 'land.s.classic.text': 'Switch on the classic theme and the game looks and feels like Championship Manager 01/02 – with tabs, Back/Next and the old background photos.', 'land.s.classic.b1': 'The squad in two columns with drag-and-drop selection', 'land.s.classic.b2': 'Player profile with every 1–20 attribute and playing career', 'land.s.classic.b3': 'Green drop-down menus, Find and Player & Staff Search',
  'land.alt.classic': 'The classic CM 01/02 theme with the 2001/02 database',
  'land.rankAiHint': 'Computer-controlled AI manager', 'land.rankAiNote': 'AI = computer-controlled managers. Play a season and you are on the list.',
  'land.nav.join': 'Join', 'land.join.kicker': 'Join us', 'land.join.title': 'Want to be part of the project?', 'land.join.text': 'CM Reborn is a fan project and there is always room for more hands. Write a few lines about yourself and what you would like to help with – and I will get back to you.', 'land.join.b1': 'Developers, designers and football data people', 'land.join.b2': 'Testers who want to try new features before everyone else', 'land.join.b3': 'Translators and people who want to help the community', 'land.join.name': 'Name', 'land.join.email': 'E-mail', 'land.join.role': 'What would you like to help with?', 'land.join.message': 'Tell us a bit about yourself', 'land.join.placeholder': 'Who are you, and what would you like to do?', 'land.join.role.developer': 'Development', 'land.join.role.designer': 'Design and graphics', 'land.join.role.data': 'Data and databases', 'land.join.role.testing': 'Testing and bug reports', 'land.join.role.translation': 'Translation', 'land.join.role.community': 'Community and content', 'land.join.role.other': 'Other', 'land.join.send': 'Send', 'land.join.sending': 'Sending…', 'land.join.thanks': 'Thanks for getting in touch!', 'land.join.thanksText': 'Your message has been received and I will reply by e-mail.', 'land.join.privacy': 'Your name and e-mail are only used to reply to you.', 'land.join.offline': 'The form only works on the main version of the game.', 'land.join.goLive': 'Go to the form', 'land.join.err.email': 'Please check your e-mail address.', 'land.join.err.limit': 'Too many messages – please try again later.', 'land.join.err.missing': 'Please fill in your name and a message of at least 10 characters.', 'land.join.err.other': 'Something went wrong – please try again.',
